        assertThat(countRows("control_event")).isZero();
    }

    @Test
    void sameStationSameTimeIsDeduplicated() {
        JsonNode first = ingest(STATION_1, T0, 8.0);
        JsonNode second = ingest(STATION_1, T0, 8.0);
