        assertThat(second.get("readingId").asLong()).isEqualTo(first.get("readingId").asLong());
        assertThat(countRows("wind_reading")).isEqualTo(1);
    }

    @Test
    void sameStationSameTimeWithDifferentSpeedConflicts() {
        ingest(STATION_1, T0, 8.0);
